+                    case 0 -> CLONE;
+                    case 1 -> HANDOFF;
+                    case 2 -> SPLIT;
+                    case 3 -> DONE;
+                    default -> throw new IllegalStateException("unknown target shard state [" + code + "]");
+                };
+            }
+        }
